package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ScienceLiveExamGeneticsEcoBank2 {
  private const val T = "ප්‍රවේණිය, ක්ෂුද්‍රජීවීන් හා පරිසර විද්‍යාව"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String = "ප්‍රවේණිය හා පරිසර විද්‍යාවට අදාළ නිවැරදි කරුණකි."
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("පරිසරයේ ස්වභාවික අපද්‍රව්‍යයක් නොවන, ජෛව හායනයට ලක් නොවන (Non-biodegradable) ද්‍රව්‍යයක් වන්නේ කුමක්ද?", "පොලිතීන් හා ප්ලාස්ටික්", "කොළ රොඩු", "කඩදාසි", "ආහාර ඉතිරි කොටස්", "පොලිතීන් වසර සිය ගණනක් පරිසරයේ නොදිරා පවතී."),
    q("ගෝලීය උෂ්ණත්වය ඉහළ යාම නිසා ඇතිවිය හැකි ප්‍රධාන දේශගුණික බලපෑමක් වන්නේ කුමක්ද?", "ධ්‍රැවීය අයිස් තට්ටු දිය වී මුහුදු මට්ටම ඉහළ යාම", "වායුගෝලීය ඔක්සිජන් දෙගුණ වීම", "භූ කම්පන සම්පූර්ණයෙන් නැවතීම", "වර්ෂාව මුළුමනින්ම නැවතීම", "මුහුදු මට්ටම ඉහළ යාමෙන් පහත් බිම් හා දූපත් ජලයෙන් යටවීමේ අවදානම පවතී."),
    q("කාබනික අපද්‍රව්‍ය ජලයට එක් වූ විට ක්ෂුද්‍රජීවීන් විසින් ඒවා වියෝජනය කිරීම සඳහා භාවිත කරන ද්‍රාව්‍ය ඔක්සිජන් ප්‍රමාණය මනින දර්ශකය කුමක්ද?", "ජෛව රසායනික ඔක්සිජන් අවශ්‍යතාව (BOD)", "pH අගය", "ආර්ද්‍රතාව", "ඝනත්වය", "BOD අගය ඉහළ වීම ජල දූෂණය අධික බව පෙන්වයි."),
    q("අන්වීක්ෂීය ඇල්ගී ආහාරයට ගන්නා කුඩා සත්ව ප්ලවාංග (Zooplankton) ජලජ පරිසර පද්ධතියක කුමන මට්ටමට අයත්ද?", "ප්‍රාථමික පාරිභෝගිකයා", "නිෂ්පාදකයා", "ද්විතීයික පාරිභෝගිකයා", "වියෝජකයා", "ශාක ප්ලවාංග (Phytoplankton) ජලජ පරිසරයේ ප්‍රධාන නිෂ්පාදකයන් වේ."),
    q("අක්මාවේ සිරෝසිස් රෝගය හෝ පිළිකා ඇති කිරීමට බලපාන දුම්වැටි දුමේ හා රසායනිකවල ඇති පිළිකා කාරක ද්‍රව්‍ය හඳුන්වන්නේ කෙසේද?", "පිළිකා කාරක (Carcinogens)", "ප්‍රතිජීවක", "එන්සයිම", "ප්‍රතිදේහ", "ඇස්බැස්ටස් හා දුම්කොළ තාර ප්‍රබල පිළිකා කාරක වේ."),
    q("වී වගාව සඳහා පොහොර හෝ ගව ගොම යොදා ගැනීමෙන් ජෛව වායුව නිපදවීමේදී නිර්වායු බැක්ටීරියා මඟින් ප්‍රධාන වශයෙන් නිපදවෙන දහන වායුව කුමක්ද?", "මීතේන් (CH₄)", "ඔක්සිජන් (O₂)", "නයිට්‍රජන් (N₂)", "සල්ෆර් ඩයොක්සයිඩ්", "මීතේන් හොඳ ගෘහස්ථ ඉන්ධනයක් වන අතර ප්‍රබල හරිතාගාර වායුවක් ද වේ."),
    q("මිනිසාගේ ඇඟිලි සලකුණු මෙන් එක් එක් පුද්ගලයාට ආවේණික DNA රටාව පරීක්ෂා කර අපරාධකරුවන් හා පීතෘත්වය හඳුනාගන්නා තාක්ෂණය කුමක්ද?", "DNA ඇඟිලි සලකුණු ක්‍රමය (DNA fingerprinting)", "X-කිරණ ඡායාරූපකරණය", "රුධිර පාරවිලයනය", "පටක රෝපණය", "සමරූපී නිවුන් දරුවන් හැර අනෙක් සෑම අයෙකුගේම DNA පැතිකඩ අනන්‍ය වේ."),
    q("ප්‍රවේණිකව රතු පැහැති හා සුදු පැහැති මල් ඇති ශාක දෙකක් මුහුම් කළ විට F₁ පරම්පරාවේ සියලු මල් රෝස පැහැ වී නම් එය කුමන ප්‍රවේණික රටාවක්ද?", "අසම්පූර්ණ ප්‍රමුඛතාව (Incomplete dominance)", "සම්පූර්ණ ප්‍රමුඛතාව", "ලිංග ප්‍රතිබද්ධතාව", "විකෘතිය", "රතු හා සුදු යන දෙකම සම්පූර්ණයෙන් ප්‍රමුඛ නොවන නිසා අතරමැදි රෝස වර්ණය ලැබේ."),
    q("AB රුධිර කාණ්ඩය හිමි පුද්ගලයෙකුගේ රතු රුධිරාණු මතුපිට A සහ B යන ප්‍රතිදේහජනක දෙකම පිහිටීම කුමන ප්‍රවේණික සිද්ධාන්තයට උදාහරණයක්ද?", "සහ-ප්‍රමුඛතාව (Codominance)", "අසම්පූර්ණ ප්‍රමුඛතාව", "නිලීනතාව", "වර්ණදේහ විකෘතිය", "Iᴬ හා Iᴮ ඇලීල දෙකම එක හා සමානව ප්‍රකාශ වේ."),
    q("වී වගාවේදී නිර්වායු බැක්ටීරියා මඟින් පිදුරු දිරාපත් කිරීමේදී පරිසරයට එක් වන හරිතාගාර වායුව කුමක්ද?", "මීතේන්", "හීලියම්", "ඔක්සිජන්", "නියොන්", "ගොයම් කුඹුරු හා ගවයන්ගේ ආමාශය මීතේන් වායුව නිපදවන මූලාශ්‍ර වේ."),
    q("නගරබද කසළ කළමනාකරණයේදී කාබනික කසළ වෙන් කර පසට පොහොර සෑදීමේ ජෛව ක්‍රියාවලිය කුමක්ද?", "කොම්පෝස්ට් නිෂ්පාදනය", "ප්ලාස්ටික් ප්‍රතිචක්‍රීකරණය", "භෂ්මීකරණය", "රසායනික දහනය", "ස්වායු ක්ෂුද්‍රජීවීන් කාබනික ද්‍රව්‍ය කොම්පෝස්ට් බවට පත් කරයි."),
    q("ක්ෂුද්‍රජීවීන්ගේ වර්ධනය නවත්වා ආහාර කල් තබා ගැනීම සඳහා අධික සීනි සාන්ද්‍රණයක් හෝ ලුණු සාන්ද්‍රණයක් යෙදීමේ මූලධර්මය කුමක්ද?", "ආස්‍රැතිය මඟින් ක්ෂුද්‍රජීවී සෛලවලින් ජලය ඉවත් කර විජලනය කිරීම", "ක්ෂුද්‍රජීවීන්ට පෝෂණය දීම", "pH අගය 7 ට ගෙන ඒම", "ඔක්සිජන් වැඩි කිරීම", "ජෑම් හා ලුණු දෙහි කල් තබා ගන්නේ මෙම ආස්‍රැති මූලධර්මයෙනි."),
    q("අධිශීතකරණයේ (-18°C) ආහාර ගබඩා කළ විට ආහාර නරක් නොවී පවතින්නේ කුමක් නිසාද?", "අඩු උෂ්ණත්වයේදී ක්ෂුද්‍රජීවීන්ගේ එන්සයිම ක්‍රියාව හා වර්ධනය අක්‍රිය වීම", "සියලු බැක්ටීරියා සදහටම මිය යාම", "ආහාරවල සීනි වැඩි වීම", "ජලය වාෂ්ප වීම", "ශීත කිරීමෙන් ක්ෂුද්‍රජීවීන් නොමැරෙන අතර ඔවුන්ගේ ක්‍රියාකාරීත්වය තාවකාලිකව නවතී."),
    q("ආහාර ටින් කිරීමේදී ආහාර නරක් කරන ක්ලොස්ට්‍රිඩියම් බොටුලිනම් (Clostridium botulinum) බැක්ටීරියාව වර්ධනය වන්නේ කුමන තත්ත්ව යටතේද?", "නිර්වායු (ඔක්සිජන් රහිත) තත්ත්ව යටතේ", "අධික ඔක්සිජන් ඇති විට", "සූර්යාලෝකය ඇති විට", "දැඩි අම්ල පරිසරයේ", "පිම්බුණු හෝ මලකඩ කෑ ටින් ආහාර භාවිත නොකළ යුතුය."),
    q("අන්තර් සබඳතා අනුව එකම වනයේ ජීවත් වන ව්‍යාඝ්‍රයා හා මුවා අතර පවතින සබඳතාව කුමක්ද?", "විලෝපිකතාව (Predation)", "සහභෝජීතාව", "අන්‍යෝන්‍යාධාරය", "පරපෝෂීතාව", "විලෝපිකයන් පරිසර පද්ධතියක ගොදුරු ජනගහනය පාලනය කරයි."),
    q("මිනිසාගේ අන්ත්‍රයේ ජීවත් වන පටි පණුවා හා මිනිසා අතර ඇති සම්බන්ධතාව කුමක්ද?", "පරපෝෂීතාව (Parasitism)", "අන්‍යෝන්‍යාධාරය", "සහභෝජීතාව", "විලෝපිකතාව", "පරපෝෂිතයා ධාරකයාගෙන් පෝෂණය ලබමින් ධාරකයාට හානි කරයි."),
    q("වනාන්තර විනාශය (Deforestation) නිසා ජල චක්‍රයට සෘජුවම සිදුවන ප්‍රධාන අහිතකර බලපෑම කුමක්ද?", "උත්ස්වේදනය අඩු වී වර්ෂාපතන රටා වෙනස් වීම හා පාංශු ඛාදනය වැඩි වීම", "භූගත ජල මට්ටම ඉහළ යාම", "සාගර ජලය අඩු වීම", "වායුගෝලීය ඔක්සිජන් වැඩි වීම", "ගස් මුල් මඟින් පස බැඳ තබා ගැනීම නැති වී නායයෑම් ඇතිවේ."),
    q("සාමාන්‍යයෙන් පරිසර දූෂණය හඳුනාගැනීමේ 'ජෛව දර්ශක' (Bio-indicators) ලෙස භාවිත කරන ජීවීන් කවුද?", "ලයිකන (Lichens)", "කපුටන්", "මීයන්", "කැරපොත්තන්", "SO₂ වායු දූෂණය අධික ප්‍රදේශවල ලයිකන වර්ධනය නොවේ."),
    q("සමුද්‍ර දූෂණය හේතුවෙන් කොරල්පර සුදු පැහැ ගැන්වීමට (Coral bleaching) ප්‍රධාන හේතුව කුමක්ද?", "සාගර ජලයේ උෂ්ණත්වය ඉහළ යාම හා ආම්ලිකතාව වැඩි වීම", "ඔක්සිජන් වැඩි වීම", "ලවණතාව ශුන්‍ය වීම", "මසුන් සංඛ්‍යාව වැඩි වීම", "උෂ්ණත්වය වැඩි වූ විට කොරල් තුළ සිටින සහජීවී ඇල්ගී ඉවත් වේ."),
    q("ජානමය වශයෙන් නිරෝගී පියෙකු හා වර්ණ අන්ධතාවේ වාහක මවකගෙන් උපදින පුතුන්ට වර්ණ අන්ධතාව වැළඳීමේ සම්භාවිතාව කීයද?", "50%", "0%", "100%", "25%", "මව XᶜX නම් පුතුන්ගෙන් අඩකට Xᶜ ලැබී රෝගී වේ."),
    q("ගෙවතු මෑ ශාකයේ කහ පැහැති බීජ (Y) කොළ පැහැති බීජවලට (y) ප්‍රමුඛ වේ නම්, Yy හා yy මුහුමකින් ලැබෙන කොළ පැහැති බීජ ප්‍රතිශතය කීයද?", "50%", "25%", "75%", "100%", "Yy × yy මුහුමේදී Yy හා yy 1:1 අනුපාතයෙන් ලැබේ."),
    q("ස්වභාවික පරිසරයේ සියලුම ආහාර දාම එකිනෙකට සම්බන්ධ වී සංකීර්ණ ජාලයක් සෑදීම හඳුන්වන්නේ කෙසේද?", "ආහාර ජාලය (Food web)", "පෝෂී මට්ටම", "ජෛව ස්කන්ධය", "පාරිසරික අවකාශය", "ආහාර ජාලයක් සංකීර්ණ වන තරමට පරිසර පද්ධතිය වඩාත් ස්ථායී වේ."),
    q("ශ්‍රී ලංකාවේ තෙත් කලාපීය වනාන්තරවල වැඩෙන නමුත් අධික ලෙස නෙළීම නිසා තර්ජනයට ලක්ව ඇති දුර්ලභ ශාකයකට උදාහරණය කුමක්ද?", "වෙනිවැල්ගැට හා සුදු හඳුන්", "තෘණ", "පොල්", "කොහොඹ", "ඖෂධීය ශාක අසීමිත ලෙස එක්රැස් කිරීම ජෛව විවිධත්වයට තර්ජනයකි."),
    q("පෘථිවි වායුගෝලයේ වර්තමානයේ පවතින කාබන් ඩයොක්සයිඩ් (CO₂) ප්‍රතිශතය ආසන්න වශයෙන් කොපමණද?", "0.04%", "4%", "21%", "78%", "වායුගෝලයේ නයිට්‍රජන් 78% ක් ද ඔක්සිජන් 21% ක් ද ආගන් 0.93% ක් ද පවතී."),
    q("මිනිසා විසින් නිපදවා ඇති වී වර්ග අතරින් විටමින් A පූර්වගාමී බීටා-කැරොටින් අඩංගු ජාන තාක්ෂණික නිපැයුම කුමක්ද?", "රන්වන් සහල් (Golden Rice)", "සුදු කැකුළු", "බාස්මතී සහල්", "සුවඳැල්", "මෙය විටමින් A ඌනතාව පිටුදැකීම සඳහා නිපදවන ලදී."),
    q("ක්ෂුද්‍රජීවීන්ගේ භාවිත අතරින් දිලීර හා බැක්ටීරියාවලින් ලබාගන්නා ඖෂධ කාණ්ඩය කුමක්ද?", "ප්‍රතිජීවක (Antibiotics)", "වේදනා නාශක", "විටමින් D", "හෝමෝන", "පෙනිසිලින්, ස්ට්‍රෙප්ටොමයිසින් සහ ටෙට්‍රාසයික්ලින් ප්‍රතිජීවක වේ."),
    q("ජලයේ හා පසේ ඇති කාබනික ද්‍රව්‍ය (උදා: තෙල් පැල්ලම් හෝ විෂ රසායන) බැක්ටීරියා යොදාගෙන හානිකර නොවන බවට පත් කිරීම කුමක්ද?", "ජෛව ප්‍රතිකර්මණය (Bioremediation)", "ජෛව සාන්ද්‍රණය", "සුපෝෂණය", "ප්‍රභාසංස්ලේෂණය", "සමහර බැක්ටීරියා සාගරයේ තෙල් කාන්දුවීම් පිරිසිදු කිරීමට යොදා ගනී."),
    q("විෂ සහිත කෘමිනාශක හෝ බැර ලෝහවලින් ගංගා ජලය දූෂණය වීම මැනීමට හා වැළැක්වීමට ගොවිතැනේදී යෙදිය යුතු හොඳම පිළියම කුමක්ද?", "ඒකාබද්ධ පළිබෝධ කළමනාකරණය (IPM)", "කෘමිනාශක දෙගුණ කිරීම", "සියලු කෘමීන් විනාශ කිරීම", "වනාන්තර එළි කිරීම", "IPM මඟින් ජෛව පාලනය හා අවම රසායන භාවිතය සිදු කෙරේ."),
    q("මිනිස් වර්ණදේහ සැකැස්මේ අංක 1 සිට 22 දක්වා ඇති යුගල හඳුන්වන්නේ කුමන නමින්ද?", "අලිංග වර්ණදේහ (Autosomes)", "ලිංග වර්ණදේහ", "ජන්මාණු", "ප්ලාස්මිඩ", "දේහ ලක්ෂණ රැසක් පාලනය කරන ජාන මේවායේ පිහිටයි."),
    q("ජීවී විද්‍යාත්මක විවිධත්වයෙන් අනූන 'තෙත් බිම්' (Wetlands) සංරක්ෂණය සඳහා ඇති ජාත්‍යන්තර සම්මුතිය කුමක්ද?", "රැම්සාර් සම්මුතිය (Ramsar Convention)", "මොන්ට්‍රියල් සම්මුතිය", "කියෝතෝ සම්මුතිය", "බාසල් සම්මුතිය", "ශ්‍රී ලංකාවේ බූන්දල හා මාදු ගඟ රැම්සාර් තෙත් බිම් වේ."),
    q("මිනිසාගේ ජීවන රටාව නිසා පරිසරයට එකතු වන ප්‍රධාන විද්‍යුත් අපද්‍රව්‍ය (E-waste) වල අඩංගු විය හැකි ඉතා විෂ සහිත බැර ලෝහ මොනවාද?", "ඊයම්, රසදිය සහ කැඩ්මියම්", "සෝඩියම් හා පොටෑසියම්", "කැල්සියම් හා මැග්නීසියම්", "යකඩ හා ඇලුමිනියම්", "ඉවතලන බැටරි හා පරිගණක කොටස් නිසි ලෙස ප්‍රතිචක්‍රීකරණය කළ යුතුය."),
    q("ප්‍රවේණික ලක්ෂණ ගැන අධ්‍යයනයේදී යම් පුද්ගලයෙකුගේ ජානමය තත්ත්වය 'Aa' ලෙස දක්වා ඇත්නම් එයින් අදහස් වන්නේ කුමක්ද?", "විෂමයුග්මක ප්‍රවේණිදර්ශයකි", "සමයුග්මක ප්‍රමුඛයකි", "සමයුග්මක නිලීනයකි", "විකෘති වූ කළලයකි", "වෙනස් ඇලීල දෙකක් (A සහ a) එකට පවතී."),
    q("කිසියම් පරිසර පද්ධතියක නිෂ්පාදකයාගෙන් පෝෂණය වන සතුන් හැඳින්වෙන්නේ කුමන නමින්ද?", "ප්‍රාථමික පාරිභෝගිකයන් (ශාක භක්ෂකයන්)", "ද්විතීයික පාරිභෝගිකයන්", "තෘතීයික පාරිභෝගිකයන්", "වියෝජකයන්", "ගවයා, මුවා හා පළගැටියා ප්‍රාථමික පාරිභෝගිකයන් වේ."),
    q("පසේ නයිට්‍රේට් ඉහළ නැංවීමට උපකාරී වන 'නයිට්‍රීකරණය' ක්‍රියාවලියේදී ඇමෝනියම් අයන (NH₄⁺) ප්‍රථමයෙන්ම කුමන අයන බවට හැරේද?", "නයිට්‍රයිට් (NO₂⁻)", "නයිට්‍රජන් වායුව (N₂)", "ඔක්සිජන් (O₂)", "කාබනේට් (CO₃²⁻)", "නයිට්‍රොසොමොනාස් බැක්ටීරියා ඇමෝනියම් නයිට්‍රයිට් බවටත් නයිට්‍රොබැක්ටර් නයිට්‍රේට් (NO₃⁻) බවටත් හරවයි."),
    q("මිරිදිය හා කරදිය හමුවන මෝය ආශ්‍රිත පරිසර පද්ධතිවල ජලයේ පවතින ලවණතාව හඳුන්වන්නේ කෙසේද?", "කිවුල් දිය (Brackish water)", "ආස්‍රැත ජලය", "මිරිදිය", "කඨින ජලය", "කඩොලාන ශාක කිවුල් දිය පරිසරයේ වැඩේ."),
    q("කිසියම් ශාකයක් හෝ සත්වයෙක් සතු ප්‍රවේණි ලක්ෂණ කෘත්‍රිමව තෝරා අභිජනනය කිරීම (Selective breeding) මගින් ලැබෙන ප්‍රධාන ප්‍රතිඵලය කුමක්ද?", "මිනිසාට අවශ්‍ය ඉහළ ගුණාත්මක ලක්ෂණ ඇති ප්‍රභේද නිපදවීම", "විකෘති රෝග වැඩි කිරීම", "ජීවීන් සම්පූර්ණයෙන් වඳ කිරීම", "DNA ඉවත් කිරීම", "වැඩි කිරි අස්වැන්නක් දෙන ගවයන් හා වැඩි අස්වනු දෙන වී ප්‍රභේද මීට උදාහරණ වේ."),
    q("සෛලීය ප්‍රවේණි විද්‍යාවේදී 'ජානයක්' (Gene) යන්න නිවැරදිව අර්ථ දක්වන්නේ කෙසේද?", "නිශ්චිත ප්‍රෝටීනයක් සංස්ලේෂණයට කේත දරන DNA කොටසකි", "සම්පූර්ණ වර්ණදේහයම වේ", "මයිටොකොන්ඩ්‍රියා පටලයයි", "සෛල බිත්ති තන්තුවකි", "වර්ණදේහයක ජාන දහස් ගණනක් පිහිටා ඇත."),
    q("මැලේරියා මදුරුවන් පාලනය කිරීම සඳහා ජලාශවලට ගප්පි මසුන් මුදා හැරීම කුමන පාලන ක්‍රමයට උදාහරණයක්ද?", "ජෛව විද්‍යාත්මක පාලනය", "රසායනික පාලනය", "භෞතික පාලනය", "විකිරණ පාලනය", "ගප්පි මසුන් මදුරු කීටයන් ආහාරයට ගනී."),
    q("ශ්‍රී ලංකාවේ ඉහළ කඳුකරයේ හෝර්ටන් තැන්න වැනි පරිසර පද්ධතිවල වැඩෙන ප්‍රධාන වෘක්ෂලතා වර්ගය කුමක්ද?", "කඳුකර වළාකුළු වනාන්තර හා පතන තෘණ භූමි", "කඩොලාන වනාන්තර", "කටු පඳුරු ලඳු කැලෑ", "තෙත් සදාහරිත පහතරට වනාන්තර", "තද සුළඟට හා සීතලට ඔරොත්තු දෙන කුරු ගස් මෙහි ඇත."),
    q("බැක්ටීරියාවල කුඩා වෘත්තාකාර අතිරේක DNA අණු වන ප්ලාස්මිඩ (Plasmids) වඩාත්ම වැදගත් වන්නේ කුමන ක්ෂේත්‍රයේද?", "ජාන ඉංජිනේරු විද්‍යාවේදී වාහකයන් ලෙස", "ප්‍රභාසංස්ලේෂණයේදී", "ආශ්වාස ක්‍රියාවලියේදී", "පසේ ඛාදනය වැළැක්වීමේදී", "ප්‍රතිසංයෝජිත DNA සෑදීමේදී ප්ලාස්මිඩ බහුලව භාවිත කෙරේ."),
    q("ලෝකයේ සාමකාමී ජීවීන්ගේ DNA ව්‍යුහය තුළ ඇඩිනීන් (A) නයිට්‍රජනීය භෂ්මය සැමවිටම යුගල වන්නේ කුමන භෂ්මය සමඟද?", "තයිමීන් (T)", "ගුවැනීන් (G)", "සයිටොසීන් (C)", "යුරැසිල් (U)", "DNA වල A–T සහ C–G ලෙස අනුපූරක භෂ්ම යුගල සාදයි."),
    q("DNA වල දක්නට නොලැබෙන, RNA අණුවල පමණක් තයිමීන් (T) වෙනුවට අඩංගු නයිට්‍රජනීය භෂ්මය කුමක්ද?", "යුරැසිල් (U)", "ඇඩිනීන් (A)", "ගුවැනීන් (G)", "සයිටොසීන් (C)", "RNA තනි දාමයක් වන අතර රයිබෝස් සීනි සහ යුරැසිල් දරයි."),
    q("ද්විමුහුම් මුහුමකදී (Dihybrid cross) විෂමයුග්මක පීතෘ ජීවීන් දෙදෙනෙකු (RrYy × RrYy) මුහුම් කළ විට F₂ පරම්පරාවේ රූපානුදර්ශී අනුපාතය කීයද?", "9 : 3 : 3 : 1", "3 : 1", "1 : 2 : 1", "1 : 1", "ලක්ෂණ යුගල දෙකක් ස්වාධීනව සම්ප්‍රේෂණය වීම මෙන්ඩල්ගේ දෙවන නියමයයි."),
    q("මව A රුධිර කාණ්ඩය (Iᴬi) ද පියා B රුධිර කාණ්ඩය (Iᴮi) ද නම්, ඔවුන්ගේ දරුවන්ට හිමිවිය හැකි රුධිර කාණ්ඩ මොනවාද?", "A, B, AB සහ O යන සියල්ලම", "A සහ B පමණි", "AB පමණි", "O පමණි", "Iᴬi × Iᴮi මඟින් IᴬIᴮ (AB), Iᴬi (A), Iᴮi (B) සහ ii (O) ලැබිය හැක."),
    q("වර්ණ අන්ධතාව ඇති පිරිමියෙකු (XᶜY) සහ නිරෝගී සමයුග්මක කාන්තාවකට (XX) උපදින දියණියන් සියලු දෙනාම කුමන තත්ත්වයේ සිටීද?", "වර්ණ අන්ධතාවේ වාහකයන් (XᶜX)", "රෝගීන්", "සම්පූර්ණයෙන් නිරෝගී (XX)", "හිමොෆීලියා වාහකයන්", "පියාගේ Xᶜ වර්ණදේහය සියලු දියණියන්ට උරුම වේ."),
    q("ජානමය වශයෙන් නොවෙනස්ව පරම්පරා ගණනාවක් තිස්සේ එකම ලක්ෂණය පෙන්වන ශාකයක් (උදා: TT හෝ tt) හඳුන්වන්නේ කුමන නමින්ද?", "ශුද්ධ අභිජනන ප්‍රභේදයක් (Pure breeding)", "දෙමුහුන් ප්‍රභේදයක්", "විකෘති ප්‍රභේදයක්", "බහුගුණ ප්‍රභේදයක්", "සමයුග්මක ජීවීන් ස්වපරාගණය කළ විට සැමවිටම සමාන ජනිතයන් ලැබේ."),
    q("පළමු පරම්පරාවේ (F₁) ජීවියෙකු නිලීන සමයුග්මක පීතෘ ජීවියෙකු (tt) සමඟ මුහුම් කර F₁ හි ප්‍රවේණිදර්ශය සොයා ගැනීම කුමක්ද?", "පරීක්ෂා මුහුම (Test cross)", "ප්‍රතිලෝම මුහුම", "ද්විමුහුම", "ස්වපරාගණය", "ප්‍රමුඛ රූපානුදර්ශයක් ඇති ජීවියා TT ද Tt ද යන්න පරීක්ෂා මුහුමෙන් සොයයි."),
    q("පටක රෝපණය හා අල, ඉඟුරු මඟින් බෝ කිරීම වැනි අලිංගික ප්‍රජනනයෙන් ලැබෙන ප්‍රධාන වාසිය කුමක්ද?", "මව් ශාකයේ හොඳ ලක්ෂණ නොවෙනස්ව පවත්වා ගැනීම", "ප්‍රවේණික විචල්‍යතා වැඩි වීම", "නව විශේෂ බිහි වීම", "බීජ සංඛ්‍යාව වැඩි වීම", "ක්ලෝන මඟින් ඒකාකාර හා ඉහළ ගුණාත්මක අස්වැන්නක් ලැබේ."),
    q("මැලේරියා රෝගය පතුරුවන පරපෝෂිතයා (Plasmodium) කුමන ක්ෂුද්‍රජීවී කාණ්ඩයට අයත්ද?", "ප්‍රොටොසෝවා", "බැක්ටීරියා", "දිලීර", "වෛරස", "ඇනෝෆිලිස් ගැහැණු මදුරුවා මඟින් මෙම ප්‍රොටොසෝවාවා සම්ප්‍රේෂණය වේ."),
    q("සුළු තුවාලයක් හරහා ශරීරගත වී මාංශපේශී තදවීමේ 'පිටගැස්ම' (Tetanus) රෝගය ඇති කරන බැක්ටීරියාව වර්ධනය වන්නේ කුමන තත්ත්වයේද?", "නිර්වායු තත්ත්ව යටතේ (ගැඹුරු තුවාලවල)", "සූර්යාලෝකයේදී", "අධික ඔක්සිජන් ඇති විට", "සීතල ජලයේදී", "Clostridium tetani පසේ ජීවත් වන නිර්වායු බැක්ටීරියාවකි."),
    q("රාත්‍රී කාලයේදී රෝග ලක්ෂණ නොපෙන්වා හෝ සෙමෙන් වර්ධනය වන, කැස්ස මගින් පැතිරෙන බැක්ටීරියා රෝගය කුමක්ද?", "ක්ෂය රෝගය (Tuberculosis)", "ඩෙංගු", "මැලේරියාව", "කොලරාව", "Mycobacterium tuberculosis පෙනහලුවලට බලපාන බැක්ටීරියාවකි."),
    q("පෙනහලු පිළිකා ඇති කිරීමට බලපාන ප්‍රධානම පාරිසරික හා හැසිරීම් සාධකය කුමක්ද?", "දුම්පානය සහ අක්‍රීය දුම්පානය", "ජලය පානය කිරීම", "පලතුරු ආහාරයට ගැනීම", "ව්‍යායාම කිරීම", "දුම්වැටි දුමේ පිළිකා කාරක රසායනික 70 කට වැඩි ප්‍රමාණයක් ඇත."),
    q("කුකුළු පොහොර, එළවළු අපද්‍රව්‍ය හා කොළ රොඩු යොදා කොම්පෝස්ට් සෑදීම වේගවත් කිරීමට අවශ්‍ය අත්‍යවශ්‍ය සාධකය කුමක්ද?", "ප්‍රමාණවත් තෙතමනය හා වාතනය (ඔක්සිජන්)", "සම්පූර්ණයෙන් වාතය වැසීම", "රසායනික වල්නාශක දැමීම", "අධි ශීතකරණය", "කොම්පෝස්ට් ගොඩ පෙරළීමෙන් ස්වායු බැක්ටීරියා වර්ධනය වේ."),
    q("කිරිවල ඇති රෝගකාරක බැක්ටීරියා විනාශ කරන නමුත් පෝෂණ ගුණය හා රසය රැක ගන්නා UHT තාප පිරියමේදී භාවිත කරන උෂ්ණත්වය කොපමණද?", "135°C – 150°C (තත්පර 2–4)", "50°C (විනාඩි 30)", "0°C", "37°C", "Ultra High Temperature ප්‍රතිකාරයෙන් කිරි පැකට් මාස ගණනක් කල් තබා ගත හැක."),
    q("විනාකිරි නිෂ්පාදනයේදී එතනෝල් ඇසිටික් අම්ලය බවට ඔක්සිකරණය කරන බැක්ටීරියාව කුමක්ද?", "ඇසිටොබැක්ටර් (Acetobacter)", "ලැක්ටොබැසිලස්", "යීස්ට්", "ඊ. කෝලයි", "මෙය ස්වායු (ඔක්සිජන් සහිත) ක්‍රියාවලියකි."),
    q("ප්ලාස්ටික් ප්‍රතිචක්‍රීකරණයේදී ආහාර ඇසුරුම් හා බෝතල්වල යට දැක්වෙන අංක 1 සිට 7 දක්වා ත්‍රිකෝණාකාර සංකේතයෙන් දැක්වෙන්නේ කුමක්ද?", "ප්ලාස්ටික් රෙසින වර්ගය (වර්ගීකරණ කේතය)", "මිල ගණන", "බර ප්‍රමාණය", "නිෂ්පාදන වර්ෂය", "උදාහරණ ලෙස 1 (PET) වතුර බෝතල් හා 2 (HDPE) කිරි බෝතල් දැක්වේ."),
    q("ගොඩබිම වෙසෙන සත්ව ප්‍රජාවක ජෛව ස්කන්ධ පිරමීඩයේ පතුලෙහි සැමවිටම සිටින්නේ කවුද?", "නිෂ්පාදකයන් (හරිත ශාක)", "ශාක භක්ෂකයන්", "මාංස භක්ෂකයන්", "පරපෝෂිතයන්", "නිෂ්පාදකයන්ගේ සමස්ත වියළි ස්කන්ධය ඉහළ මට්ටම්වලට වඩා බොහෝ සෙයින් වැඩිය."),
    q("කලාපීය වශයෙන් සමාන දේශගුණික තත්ත්ව හා ශාක ප්‍රජාවන් සහිත විශාල පාරිසරික කලාප (උදා: නිවර්තන වැසි වනාන්තර, තෘණ භූමි) හඳුන්වන්නේ කෙසේද?", "බයෝම (Biomes)", "ජනගහන", "වාසස්ථාන", "ජාන සංචිත", "උෂ්ණත්වය හා වර්ෂාපතනය ලෝකයේ ප්‍රධාන බයෝම තීරණය කරයි."),
    q("ශ්‍රී ලංකාවේ වියළි කලාපයේ වැසි ජලය රැස් කිරීම සඳහා ඉදි කර ඇති පැරණි වැව් පද්ධති කුමන ආකාරයේ පරිසර පද්ධතියක්ද?", "කෘත්‍රිම ජලජ පරිසර පද්ධතියකි", "සමුද්‍ර පරිසර පද්ධතියකි", "කාන්තාර පරිසර පද්ධතියකි", "හිම කඳු පරිසර පද්ධතියකි", "එල්ලංගා වැව් පද්ධති ජල කළමනාකරණයට හා ජෛව විවිධත්වයට උපකාරී වේ."),
    q("කලපු හා මෝය පරිසරවල වැඩෙන කඩොලාන ශාකවල (උදා: කඩොල්) ජලයෙන් යටවන මඩ පසේ ශ්වසනය සඳහා ඇති විශේෂිත මුල් මොනවාද?", "වායුධර මුල් (Pneumatophores / ශ්වසන මුල්)", "ආලම්බ මුල් පමණි", "ආස්‍රැති මුල්", "නූල් මුල්", "ඔක්සිජන් අඩු මඩ පසෙන් ඉහළට වැඩෙන මෙම මුල් වායු හුවමාරුව සිදු කරයි."),
    q("කඩොලාන ශාකවල බීජ මව් ශාකය මත තිබියදීම ප්‍රරෝහණය වී කඳුකර කෙටි මුල් සහිත පැළයක් ලෙස බිම වැටීම හඳුන්වන්නේ කුමන නමින්ද?", "ජලාබුජතාව (Vivipary)", "සූර්යවර්තනය", "ස්වපරාගණය", "විකෘතිය", "මඩ පසෙහි කෙළින්ම සිර වී පහසුවෙන් ස්ථාපිත වීමට මෙය අනුවර්තනයකි."),
    q("වඳවී යාමේ තර්ජනයට ලක්ව ඇති ජීවී විශේෂ රැක ගැනීම සඳහා නීතිමය රැකවරණය සපයන ශ්‍රී ලංකාවේ ප්‍රධාන පනත කුමක්ද?", "වන සත්ව හා වෘක්ෂලතා ආරක්ෂක ආඥා පනත", "කම්කරු පනත", "වාරිමාර්ග පනත", "මෝටර් රථ පනත", "ආවේණික හා ආරක්ෂිත සතුන් දඩයම් කිරීම හා ළඟ තබා ගැනීම මෙමගින් තහනම් වේ."),
    q("ශ්‍රී ලංකාවේ ආවේණික පක්ෂියෙකු හෝ සත්වයෙකු වන්නේ පහත සඳහන් කවරෙක්ද?", "ශ්‍රී ලංකා වළිකුකුළා (Gallus lafayettii)", "පරෙවියා", "ගෙවල් කපුටා", "ඉන්දියානු මොණරා", "ශ්‍රී ලංකා වළිකුකුළා ජාතික පක්ෂියා ද වේ."),
    q("කෘෂිකාර්මික පසකට වසුරු යෙදීම (Mulching) මඟින් ලැබෙන ප්‍රධාන පාරිසරික ප්‍රතිලාභය කුමක්ද?", "පාංශු ඛාදනය වැළැක්වීම හා පසේ තෙතමනය රැක ගැනීම", "පසේ ලවණතාව වැඩි කිරීම", "වල් පැළෑටි වේගවත් කිරීම", "පසේ ක්ෂුද්‍රජීවීන් විනාශ කිරීම", "පිදුරු හෝ වියළි කොළ යෙදීමෙන් පස දිරාපත් වී කොම්පෝස්ට් ද සෑදේ."),
    q("මුහුදු ජලයේ ආම්ලිකතාව ඉහළ යාම (Ocean acidification) සිදු වන්නේ වායුගෝලයේ කුමන වායුව සාගර ජලයේ වැඩිපුර දිය වීමෙන්ද?", "කාබන් ඩයොක්සයිඩ් (CO₂)", "ඔක්සිජන් (O₂)", "නයිට්‍රජන් (N₂)", "මීතේන් (CH₄)", "CO₂ ජලයේ දිය වී කාබනික් අම්ලය (H₂CO₃) සාදමින් සිප්පි කටු හා කොරල් දිය කරයි."),
    q("වීදි ලාම්පු හා ගෙවතු ආලෝකකරණයෙන් රාත්‍රී කාලයේ කෘමීන්ගේ හා පක්ෂීන්ගේ හැසිරීමට බාධා වීම හඳුන්වන්නේ කුමන දූෂණයක් ලෙසද?", "ආලෝක දූෂණය (Light pollution)", "ශබ්ද දූෂණය", "තාප දූෂණය", "පාංශු දූෂණය", "අධික කෘත්‍රිම ආලෝකය නිසා කැස්බෑ පැටවුන් හා නිශාචර සතුන් මංමුලා වේ."),
    q("ජල විදුලි බලාගාර හෝ කර්මාන්තශාලා සිසිලන ජලය උණුසුම්ව ගංගාවලට මුදා හැරීමෙන් ජලජ ජීවීන්ට සිදුවන බලපෑම කුමක්ද?", "තාප දූෂණය (ජලයේ ද්‍රාව්‍ය ඔක්සිජන් අඩු වීම)", "ජලයේ අයිස් සෑදීම", "ලවණතාව අඩු වීම", "ආලෝකය වැඩි වීම", "උෂ්ණත්වය ඉහළ යත්ම ජලයේ O₂ ද්‍රාව්‍යතාව අඩු වී මසුන් හුස්ම ගැනීමට අපහසු වේ."),
    q("ඉහළ කඳු බෑවුම්වල පාංශු ඛාදනය වැළැක්වීමට භාවිත කරන වඩාත් සුදුසු කෘෂිකාර්මික ක්‍රමය කුමක්ද?", "සමෝච්ච හෙල්මළු වගාව හා ගල් වැටි යෙදීම", "බෑවුම දිගේ සෘජුව කාණු කැපීම", "සියලු ගස් කපා දැමීම", "වල් පැළ ගිනි තැබීම", "ජලය ගලා යන වේගය අඩු කර පස සේදී යාම නවතයි."),
    q("වෛරසයක් බැක්ටීරියාවකට ආසාදනය වී ගුණනය වන විට එම වෛරසය හඳුන්වන්නේ කුමන නමින්ද?", "බැක්ටීරියා භක්ෂකය (Bacteriophage)", "ප්ලාස්මිඩය", "ලයිකනය", "ප්‍රොටොසෝවාවා", "බැක්ටීරියා භක්ෂක ජාන ඉංජිනේරු විද්‍යාවේදී වාහකයන් ලෙස ද භාවිත කෙරේ."),
    q("රෝග වැළැක්වීම සඳහා මිනිස් සිරුර තුළ නිපදවෙන හෝ එන්නත් කරන ප්‍රතිදේහ මඟින් පවතින ආරක්ෂාව කුමක්ද?", "ප්‍රතිශක්තිය (Immunity)", "ආසාත්මිකතාව", "විකෘතිය", "සහභෝජීතාව", "මව්කිරි හරහා දරුවාට ලැබෙන්නේ ස්වාභාවික අක්‍රීය ප්‍රතිශක්තියයි."),
    q("පානීය ජලය ක්ලෝරීනීකරණය කිරීමේ ප්‍රධාන අරමුණ කුමක්ද?", "රෝගකාරක බැක්ටීරියා හා ක්ෂුද්‍රජීවීන් විනාශ කිරීම", "ජලයේ කඨිනත්වය වැඩි කිරීම", "ජලය මිදීම වැළැක්වීම", "ලවණ රසය වැඩි කිරීම", "ක්ලෝරීන් ප්‍රබල විෂබීජ නාශකයකි."),
    q("මිනිසාගේ ජීවන තත්ත්වය හා පරිසර සංරක්ෂණය අතර සබඳතාවේදී 'ප්‍රතිභාවිතය' (Reuse) සඳහා හොඳම උදාහරණය කුමක්ද?", "වීදුරු බෝතල් හා රෙදි බෑග් නැවත නැවත භාවිත කිරීම", "ප්ලාස්ටික් උණු කර අලුත් බෝතල් සෑදීම", "කසළ ගිනි තැබීම", "අනවශ්‍ය ඇසුරුම් ප්‍රතික්ෂේප කිරීම", "ප්‍රතිචක්‍රීකරණයේදී අමුද්‍රව්‍යයක් නැවත සැකසෙන අතර ප්‍රතිභාවිතයේදී එලෙසම ගනී."),
    q("ජානමය වශයෙන් සමරූපී දරුවෙකු හෝ සත්වයෙකු කෘත්‍රිමව නිපදවීම (උදා: ඩොලී බැටළුවා) කුමන නමින් හැඳින්වේද?", "ක්ලෝනකරණය (Cloning)", "මුහුම් කිරීම", "විකෘති කිරීම", "සංසේචනය", "දේහ සෛල න්‍යෂ්ටියක් න්‍යෂ්ටිය ඉවත් කළ ඩිම්බයකට ඇතුළු කිරීමෙන් මෙය සිදු කළේය."),
    q("එකම ජීවී විශේෂයේ පුද්ගලයන් අතර දක්නට ලැබෙන, පරිසර සාධක හා බහු ජාන නිසා ඇතිවන අඛණ්ඩ වෙනස්වීම්වලට උදාහරණය කුමක්ද?", "මිනිසාගේ උස සහ ශරීර බර", "ABO රුධිර කාණ්ඩ", "දිව රෝල් කිරීමේ හැකියාව", "කණ්පෙති සම්බන්ධ වූ හෝ නිදහස් බව", "රුධිර කාණ්ඩ හා දිව රෝල් කිරීම අඛණ්ඩ නොවන (Discrete) විචල්‍යතා වේ."),
    q("අඛණ්ඩ නොවන විචල්‍යතාවක් (Discontinuous variation) පෙන්වන ලක්ෂණයක ප්‍රස්තාරික නිරූපණය කෙබඳුද?", "පැහැදිලිව වෙන් වූ කාණ්ඩ කිහිපයක් ලෙස දිස්වීම", "සීනුවක හැඩැති සුමට වක්‍රයක් වීම", "සෘජු තිරස් රේඛාවක් වීම", "ශුන්‍ය වීම", "මිනිසාගේ ABO රුධිර කාණ්ඩ හතරටම අතරමැදි අගයන් නොමැත."),
    q("ගොඩබිම ආහාර දාමයක හිරු එළියෙන් ශක්තිය අවශෝෂණය කර ගන්නා නිෂ්පාදකයන් භාවිත කරන්නේ සමස්ත සූර්ය ශක්තියෙන් ආසන්න වශයෙන් කොපමණ ප්‍රතිශතයක්ද?", "1% – 2% පමණ", "50% පමණ", "90% පමණ", "100% ම", "සූර්යාලෝකයෙන් වැඩි කොටසක් පරාවර්තනය වීම හා තාපය ලෙස අපතේ යාම සිදුවේ."),
    q("වැවක ජලය මත අධිකව ඇල්ගී පිපීම (Algal bloom) සිදු වූ විට එම ජලාශයේ පතුලේ ඇති ජලජ ශාක මිය යාමට ප්‍රධාන හේතුව කුමක්ද?", "සූර්යාලෝකය ජලය තුළට කාන්දු වීම වැළකීම", "ජලයේ ලුණු වැඩි වීම", "ජලය ඉතා සීතල වීම", "මසුන් වැඩි වීම", "මතුපිට ඇල්ගී ස්තරය ආලෝකය අවහිර කරන බැවින් පතුලේ ශාකවලට ප්‍රභාසංස්ලේෂණය කළ නොහැක."),
    q("පසේ ජීවත් වන මළ සිරුරු හා යූරියා වියෝජනය කර ඇමෝනියා (NH₃) නිපදවන ක්ෂුද්‍රජීවී ක්‍රියාවලිය කුමක්ද?", "ඇමෝනීකරණය (Ammonification)", "විනයිට්‍රීකරණය", "ප්‍රභාසංස්ලේෂණය", "වාෂ්පීකරණය", "මෙය නයිට්‍රජන් චක්‍රයේ වැදගත් පියවරකි."),
    q("අන්වීක්ෂයෙන් නිරීක්ෂණය කළ විට බැක්ටීරියා සෛල ශාක හා සත්ව සෛලවලින් වෙන් කොට හඳුනා ගත හැකි ප්‍රධාන ලක්ෂණය කුමක්ද?", "පටලයකින් වට වූ සංවිධානාත්මක න්‍යෂ්ටියක් නොමැති වීම", "රයිබොසෝම නොමැති වීම", "DNA නොමැති වීම", "සෛල ප්ලාස්මය නොමැති වීම", "බැක්ටීරියා ප්‍රාග්න්‍යෂ්ටික (Prokaryotic) ජීවීන් වේ."),
    q("සංඛ්‍යා පිරමීඩයක් 'උඩුකුරු' (Inverted) හැඩයක් ගැනීමට හොඳම උදාහරණය කුමක්ද?", "තනි විශාල ගසක් → කුරුල්ලන් → කුරුල්ලන් මත සිටින උකුණන්", "තෘණ → හාවා → නරියා", "ශාක ප්ලවාංග → කුඩා මසුන් → විශාල මසුන්", "වී ගොයම → මීයා → සර්පයා", "තනි නිෂ්පාදකයෙකු මත පාරිභෝගිකයන් හා පරපෝෂිතයන් දහස් ගණනක් යැපේ."),
    q("පළමු වරට රෝග නාශක එන්නතක් (වසූරිය එන්නත) සොයා ගැනීමේ ගෞරවය හිමිවන විද්‍යාඥයා කවුද?", "එඩ්වඩ් ජෙනර්", "ලුවී පාස්චර්", "ඇලෙක්සැන්ඩර් ෆ්ලෙමින්", "රොබට් කොක්", "එඩ්වඩ් ජෙනර් ගව වසූරිය යොදා මිනිස් වසූරියට ප්‍රතිශක්තිය ඇති කළේය."),
    q("මිනිසාගේ ලිංගිකත්වය තීරණය වීමේදී දියණියක් හෝ පුතෙකු බිහිවීමේ සම්භාවිතාව කොපමණද?", "දියණියක් 50% : පුතෙකු 50%", "දියණියක් 75% : පුතෙකු 25%", "දියණියක් 100%", "පුතෙකු 100%", "පිරිමින් X සහ Y ශුක්‍රාණු සමාන ප්‍රමාණවලින් නිපදවන බැවිනි."),
    q("සමහර බැක්ටීරියා අහිතකර පරිසර තත්ත්වවලදී (උදා: අධික උණුසුම හෝ වියළි බව) ආරක්ෂා වීමට සාදාගන්නා ඝන බිත්ති සහිත ව්‍යුහය කුමක්ද?", "අන්තඃබීජාණු (Endospores)", "ප්ලාස්මිඩ", "කශිකා", "රයිබොසෝම", "සාමාන්‍ය ජලය උතුරුවා පවා සමහර බැක්ටීරියා අන්තඃබීජාණු විනාශ කළ නොහැක."),
    q("පොල් තෙල් හෝ ස්වාභාවික රබර් කර්මාන්තශාලා අපද්‍රව්‍ය ගංගාවලට මුදා හැරීමට පෙර පිරිපහදු කිරීමේදී යොදා ගන්නා ජෛව ටැංකිවල සිදුවන්නේ කුමක්ද?", "ක්ෂුද්‍රජීවීන් මගින් කාබනික අපද්‍රව්‍ය වියෝජනය කිරීම", "ජලය වාෂ්ප කිරීම", "අපද්‍රව්‍ය ප්ලාස්ටික් බවට හැරවීම", "බැර ලෝහ නිපදවීම", "පිරිපහදු කළ ජලයේ BOD අගය බොහෝ සෙයින් අඩු වේ."),
    q("කිසියම් පරිසර පද්ධතියක වසරක් තුළ සිදුවන 'නැවත ජනනය කළ නොහැකි' (Non-renewable) ස්වාභාවික සම්පතක් වන්නේ කුමක්ද?", "ඛනිජ තෙල් හා ගල් අඟුරු", "සූර්ය ශක්තිය", "සුළං බලය", "ජල චක්‍රය", "ෆොසිල ඉන්ධන සෑදීමට වසර මිලියන ගණනක් ගත වේ."),
    q("ගෙවතු කෘෂිකර්මාන්තයේදී මල් පිපීම හා පරාගණය සඳහා උපකාරී වන ප්‍රධාන පරිසර හිතකාමී කෘමීන් කවුද?", "මීමැස්සන් හා සමනලුන්", "මදුරුවන්", "කැරපොත්තන්", "වේයන්", "පළිබෝධනාශක අධික ලෙස ඉසීම පරාගකාරක කෘමීන් විනාශ කරයි."),
    q("DNA තුළ සිදුවන වෙනස්වීම්වලින් 'වර්ණදේහ සංඛ්‍යාව' වෙනස් වීම නිසා ඇතිවන ජානමය ආබාධයක් වන්නේ කුමක්ද?", "ඩවුන් සින්ඩ්‍රෝමය", "හිමොෆීලියාව", "වර්ණ අන්ධතාව", "තැලසීමියාව", "තැලසීමියාව හා හිමොෆීලියාව තනි ජාන විකෘති වන අතර ඩවුන් සින්ඩ්‍රෝමය වර්ණදේහ විකෘතියකි."),
    q("කාබනික ගොවිතැනේදී පසේ පාංශු වාතනය හා සාරවත් බව වැඩි කරන පරිසර හිතකාමී අපෘෂ්ඨවංශී සත්වයා කවුද?", "ගැඩවිලා (Earthworm)", "කූඩැල්ලා", "පටි පණුවා", "මැක්කා", "ගැඩවිලන් පස බුරුල් කර කාබනික ද්‍රව්‍ය මිශ්‍ර කරයි."),
    q("විෂ සහිත කෘමිනාශක හෝ බැර ලෝහ ජලයේ දිය වී ඇති විට පළමුව ඒවා ශරීරගත වන්නේ කුමන ජීවීන්ටද?", "ජලජ ශාක හා ශාක ප්ලවාංගවලට", "උකුස්සන්ට", "සිංහයන්ට", "වවුලන්ට", "ආහාර දාමයේ පහළම මට්ටමෙන් ආරම්භ වී ඉහළට යත්ම සාන්ද්‍රණය වේ."),
    q("ලංකාවේ ශුෂ්ක හා වියළි කලාපීය වනාන්තරවල ශාක දක්වන ප්‍රධාන අනුවර්තනයක් වන්නේ කුමක්ද?", "කුඩා පත්‍ර, කටු පැවතීම හා ඝන උච්චර්මය", "අතිශය විශාල තුනී පත්‍ර", "වායුධර මුල් තිබීම", "ජලයේ පාවෙන කඳන් තිබීම", "උත්ස්වේදනයෙන් සිදුවන ජල හානිය අවම කිරීම මෙහි අරමුණයි."),
    q("ගෘහස්ථ මට්ටමින් පරිසරයට එකතු වන 'විද්‍යුත් අපද්‍රව්‍ය' (E-waste) කළමනාකරණය කිරීමට ඇති නිවැරදිම ක්‍රමය කුමක්ද?", "බලයලත් E-waste ප්‍රතිචක්‍රීකරණ මධ්‍යස්ථාන වෙත භාර දීම", "සාමාන්‍ය කසළ සමඟ ගිනි තැබීම", "ගංගාවලට විසි කිරීම", "වත්තේ වළ දැමීම", "බැර ලෝහ පසට හා භූගත ජලයට එකතු වීම මෙමගින් වළකී."),
    q("ප්‍රවේණික රෝගයක් වන 'රෝස පැහැ කණ්පෙති' වැනි හෝ ලේ කැටි නොගැසෙන හිමොෆීලියා රෝගය ස්ත්‍රීන්ට වඩා පිරිමින් අතර බහුල වීමට හේතුව කුමක්ද?", "පිරිමින්ට X වර්ණදේහය එකක් පමණක් (XY) තිබීම", "පිරිමින්ට Y වර්ණදේහ දෙකක් තිබීම", "ස්ත්‍රීන්ට X වර්ණදේහ නොමැති වීම", "පිරිමින්ගේ රුධිර පීඩනය වැඩි වීම", "පිරිමින්ගේ එකම X වර්ණදේහයේ නිලීන ජානය පිහිටි විට එය වසන් කිරීමට අනෙක් ඇලීලයක් නැත."),
    q("ක්ෂුද්‍රජීවීන් භාවිතයෙන් පොල් රා විනාකිරි කිරීම හා කිරි මුදවපු කිරි කිරීම යන දෙකම සිදු වන්නේ කුමන ජෛව රසායනික ක්‍රියාවලිය මතද?", "ක්ෂුද්‍රජීවී පැසවීම (Fermentation)", "ප්‍රභාසංස්ලේෂණය", "ආස්‍රැතිය", "ස්ඵටිකීකරණය", "ක්ෂුද්‍රජීවීන් කාබනික සංයෝග එන්සයිම මගින් වෙනත් ප්‍රයෝජනවත් සංයෝග බවට හරවයි."),
    q("ලෝකයේ සමස්ත ජීවී පද්ධතිය සහ ඒවා සමඟ අන්තර් ක්‍රියා කරන වායුගෝලය, ජලගෝලය හා ශිලාගෝලය එක්ව සෑදෙන විශාලතම පරිසර ඒකකය කුමක්ද?", "ජෛවගෝලය (Biosphere)", "ප්‍රජාව", "ජනගහනය", "නිකේතනය", "පෘථිවියේ ජීවය පවතින සමස්ත කලාපය ජෛවගෝලයයි.")
  )
}
